// src/app/admin/contact/page.tsx
import Navbar from "@/components/Navbar";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";

type ContactItem = {
    id: number;
    name: string;
    email: string;
    mobile: string;
    created_at: string;
};

async function getApplications(): Promise<ContactItem[]> {
    const cookieStore = cookies();
    const token = (await cookieStore).get("admin_token")?.value;

    if (!token) {
        redirect("/login");
    }

    const res = await fetch(`${process.env.NEXT_PUBLIC_BASE_URL}/api/contact`, {
        cache: "no-store",
        headers: {
            cookie: `admin_token=${token}`,
        },
    });

    if (!res.ok) {
        if (res.status === 401) {
            redirect("/login");
        }
        throw new Error("Failed to fetch applications");
    }

    return res.json();
}

export default async function ContactPage() {
    const contacts = await getApplications();

    return (
        <div className="min-h-screen bg-gray-50">
            <Navbar />

            <div className="max-w-7xl mx-auto px-6 py-10">
                <h1 className="text-3xl font-semibold text-gray-800 mb-8">
                    Contact Requests
                </h1>

                <div className="bg-white shadow-sm rounded-xl border border-gray-200 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-gray-100 text-gray-600 uppercase text-xs tracking-wider">
                                <tr>
                                    <th className="px-6 py-4">S.No</th>
                                    <th className="px-6 py-4">Name</th>
                                    <th className="px-6 py-4">Email</th>
                                    <th className="px-6 py-4">Mobile</th>
                                    <th className="px-6 py-4">Date</th>
                                </tr>
                            </thead>

                            <tbody className="divide-y divide-gray-200">
                                {contacts.length === 0 ? (
                                    <tr>
                                        <td
                                            colSpan={5}
                                            className="px-6 py-10 text-center text-gray-500"
                                        >
                                            No contact requests found.
                                        </td>
                                    </tr>
                                ) : (
                                    contacts.map((item, i) => (
                                        <tr
                                            key={item.id}
                                            className="hover:bg-gray-50 transition-colors"
                                        >
                                            <td className="px-6 py-4 font-medium text-gray-700">
                                                {i + 1}
                                            </td>
                                            <td className="px-6 py-4 text-gray-800">
                                                {item.name}
                                            </td>
                                            <td className="px-6 py-4 text-blue-600">
                                                {item.email}
                                            </td>
                                            <td className="px-6 py-4 text-gray-700">
                                                {item.mobile}
                                            </td>
                                            <td className="px-6 py-4 text-gray-500">
                                                {new Date(item.created_at).toLocaleDateString()}
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
}